from pathlib import Path
import json,re,html
from markdown_it import MarkdownIt
R=Path(__file__).resolve().parents[1]
md=MarkdownIt('commonmark',{'html':False}).enable('table')
docs=[]
for p in sorted((R/'docs').glob('*.md')):
 text=p.read_text();title=text.splitlines()[0].lstrip('# ')
 out=md.render(text)
 out=re.sub(r'<table>',r'<div class="tablewrap"><table>',out).replace('</table>','</table></div>')
 out=re.sub(r'<td>(R\d+)</td>',r'<td id="source-\1">\1</td>',out)
 docs.append({'id':p.stem,'title':title,'html':out,'text':text})
(R/'docs-registry.json').write_text(json.dumps([{'id':d['id'],'title':d['title']} for d in docs],ensure_ascii=False,indent=2))
stages=json.loads((R/'templates/stage-registry.json').read_text())['stages']
cases=json.loads((R/'templates/acceptance-matrix.json').read_text())['cases']
prompt=(R/'CODEX_START_PROMPT.txt').read_text()
